using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.API.Data; using RaceDay.API.DTOs; using RaceDay.API.Models;
namespace RaceDay.API.Controllers;
[ApiController,Route("api")]
public class ResultsController(RaceDayContext db):ControllerBase
{
 /// <summary>Records a finishing time and position for an enrolment in the Organiser event.</summary>
 [Authorize(Roles="Organiser"),HttpPost("results"),ProducesResponseType(StatusCodes.Status201Created),ProducesResponseType(StatusCodes.Status403Forbidden),ProducesResponseType(StatusCodes.Status409Conflict)] public async Task<IActionResult> Create(ResultRequest request){var en=await db.Enrolments.Include(x=>x.Event).FirstOrDefaultAsync(x=>x.EnrolmentId==request.EnrolmentId);if(en is null)return NotFound(new{message="Enrolment not found."});if(en.Event!.OrganiserId!=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!))return Forbid();if(await db.Results.AnyAsync(x=>x.EnrolmentId==request.EnrolmentId))return Conflict(new{message="A result already exists for this enrolment."});if(request.Position is null || request.Position <= 0)return BadRequest(new{message="A positive finishing position is required."});var result=new Result{EnrolmentId=request.EnrolmentId,FinishTime=request.FinishTime,Position=request.Position,Notes=request.Notes};db.Results.Add(result);en.Status="Completed";await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=result.ResultId},result);}
 /// <summary>Lists results for an event, ordered by finishing position.</summary>
 [HttpGet("events/{eventId:int}/results"),ProducesResponseType(StatusCodes.Status200OK),ProducesResponseType(StatusCodes.Status404NotFound)] public async Task<IActionResult> ForEvent(int eventId){if(!await db.Events.AnyAsync(x=>x.EventId==eventId))return NotFound();return Ok(await db.Results.AsNoTracking().Include(x=>x.Enrolment).ThenInclude(x=>x!.Participant).Include(x=>x.Enrolment).ThenInclude(x=>x!.Category).Where(x=>x.Enrolment!.EventId==eventId).OrderBy(x=>x.Position).Select(x=>new{x.ResultId,x.EnrolmentId,x.FinishTime,x.Position,x.Notes,participantName=x.Enrolment!.Participant!.FirstName+" "+x.Enrolment.Participant.LastName,category=x.Enrolment.Category!.Name}).ToListAsync());}
 /// <summary>Returns one result by its identifier.</summary>
 [HttpGet("results/{id:int}"),ProducesResponseType(StatusCodes.Status200OK),ProducesResponseType(StatusCodes.Status404NotFound)] public async Task<IActionResult> Get(int id){var r=await db.Results.AsNoTracking().Include(x=>x.Enrolment).ThenInclude(x=>x!.Participant).Include(x=>x.Enrolment).ThenInclude(x=>x!.Event).FirstOrDefaultAsync(x=>x.ResultId==id);return r is null?NotFound():Ok(new{r.ResultId,r.EnrolmentId,r.FinishTime,r.Position,r.Notes,participantId=r.Enrolment!.ParticipantId,participantName=r.Enrolment.Participant!.FirstName+" "+r.Enrolment.Participant.LastName,eventId=r.Enrolment.EventId,eventTitle=r.Enrolment.Event!.Title});}
 /// <summary>Lists results belonging to the authenticated Participant.</summary>
 [Authorize(Roles="Participant"),HttpGet("results/me"),ProducesResponseType(StatusCodes.Status200OK)] public async Task<IActionResult> Mine(){var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);return Ok(await db.Results.AsNoTracking().Include(x=>x.Enrolment).ThenInclude(x=>x!.Event).Where(x=>x.Enrolment!.ParticipantId==id).Select(x=>new{x.ResultId,x.EnrolmentId,x.FinishTime,x.Position,x.Notes,eventTitle=x.Enrolment!.Event!.Title}).ToListAsync());}
}